            return `${prefix}${space1}${String(monthNumber).padStart(2, '0')}/${String(day).padStart(2, '0')}/${year}${hyphenSpacing}${String(monthNumber).padStart(2, '0')}/${String(day).padStart(2, '0')}/${year + 1}`;
          }

